# Check the unique values in the documentation columns to understand the encoding
for col in documentation_columns:
    print(f"Unique values in {col}: {df[col].unique()}")

# Recalculate the percentage of respondents indicating that they use each documentation format, considering 'quoted' as usage and excluding '-77'
percentage_used = {}
for col in documentation_columns:
    # Filter out rows with '-77' and count the number of 'quoted' responses
    quoted_count = df[(df[col] == 'quoted') & (df[col] != '-77')].shape[0]
    total_valid = df[df[col] != '-77'].shape[0]
    if total_valid == 0:
        percentage = 0.0
    else:
        percentage = (quoted_count / total_valid) * 100
    percentage_used[col] = percentage

percentage_used
